{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "17β-Estradiol, which shares the full estradiol scaffold with the query and differs only by the absence of the 16α-hydroxy group, has an absolute oral bioavailability of about 5% in humans; this is the most direct and transferable evidence and supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "2-Methoxyestradiol, another hydroxylated estradiol metabolite, has oral bioavailability of only 1–2% in patients, showing that adding polar substituents to the estradiol core does not improve and likely further lowers systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Estetrol, a more hydroxylated estradiol analogue, is reported to have high and dose-related oral bioavailability in humans; this is contradictory in direction but is qualitative and depends on estetrol's distinct 15α-hydroxy metabolic profile, so it transfers only weakly to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Ethinylestradiol shows oral bioavailability around 38% in women, but this high value is attributable to the 17α-ethynyl group that protects the 17β-hydroxy from first-pass conjugation; the query lacks this protective group, so this evidence does not support high F for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Moxestrol has an absolute oral bioavailability of 35% in humans, but it contains both a 17α-ethynyl group and an 11β-methoxy group that reduce first-pass metabolism; these stabilizing substituents are absent in the query, so this high-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is estriol, a 16α-hydroxylated estradiol analogue. The closest high-transfer evidence, estradiol, shows absolute oral bioavailability of only ~3–11% in humans; the additional 16α-hydroxy group increases polarity and phase II conjugation liability, supporting F < 20%. High-F analogues (ethinylestradiol, moxestrol, estetrol) owe their improved bioavailability to protective substituents absent in the query, so they do not override the low-F conclusion.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for estriol itself was provided; the prediction relies on close analogues.",
    "The estetrol high-bioavailability record is qualitative and its 15α-hydroxy metabolic protection may not transfer to estriol.",
    "Quantitative human absolute F for estriol would reduce uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

